INSERT INTO changelog (title, body, created_at) VALUES ('Meta: перевірка токена прямо в Налаштуваннях', 'Налаштування → Конектори → Meta Ads: зверху картка «Перевірка токена» — чи токен працює, термін (вічний / до дати), скільки дозволів (клік — список) і які сторінки він бачить разом з їхнім Instagram (@імʼя і ID). Новий токен вставляєш через кнопку «Токен» праворуч угорі → «Зберегти»: система сама перевірить і підхопить без перезапуску. Для вічного токена системного користувача більше не висить «онови токен через 60 днів».', datetime('now'));
